"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[292],{2292:(e,a,i)=>{i.d(a,{b:()=>t});let t=[{id:"guide-arrival-mle",slug:"arrival-at-velana-international-airport-mle",category:"arrival-transfers",categoryLabel:{en:"Arrival & Transfers",zh:"抵达与交通接驳"},title:{en:"Arrival at Velana International Airport (MLE): Step-by-Step Guide",zh:"维拉纳国际机场 (MLE) 入境与换乘全流程指南"},summary:{en:"What to expect upon landing on Hulhul\xe9 Island (MLE), including immigration clearance, customs screening, bank and SIM counters, and walking directly across to the speedboat arrival jetties.",zh:"详解降落马累机场岛（Hulhul\xe9）后的入境边检、海关安检、ATM与电话卡柜台位置，以及出航站楼步行1分钟直达快艇码头的衔接流程。"},heroImage:{url:"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/Velana_International_Airport%2C_Male%2C_Maldives_%28MLE%29.jpg/1920px-Velana_International_Airport%2C_Male%2C_Maldives_%28MLE%29.jpg",alt:{en:"Aerial view of the island runway at Velana International Airport (MLE) in North Mal\xe9 Atoll, Maldives",zh:"马尔代夫维拉纳国际机场（MLE）跨海跑道与泻湖航拍"},credit:"Photo by Simon_sees / Wikimedia Commons (CC BY 2.0)"},lastReviewedDate:"2026-10-15",readingTimeMinutes:5,keyTakeaways:{en:["Velana International Airport (IATA: MLE) occupies Hulhul\xe9 Island immediately adjacent to Mal\xe9 and Hulhumal\xe9.","The speedboat departure jetties and Domestic Terminal are located directly outside the International Arrivals hall—no taxi is needed unless staying overnight in Mal\xe9 or Hulhumal\xe9.","All incoming baggage undergoes mandatory X-ray screening for prohibited items (including duty-free alcohol and pork products) before exiting customs."],zh:["维拉纳国际机场（代码：MLE）位于紧邻首都马累的机场岛（Hulhul\xe9），与马累及胡鲁马累通过跨海大桥相连。","快艇出发码头与国内航站楼就在国际到达大厅正门外步行1–3分钟处——直接前往居民岛无需打车进入马累市区。","所有托运与随身行李在出海关前均需通过X光安检，严禁携带任何含酒精饮品（含免税店购买的酒类）、猪肉制品及无人机（未提前申报许可时）。"]},sections:[{heading:{en:"1. Immigration & Baggage Claim",zh:"1. 入境边检与行李提取"},paragraphs:[{en:"After disembarking at Velana International Airport (MLE), follow signs to Immigration. Ensure you have completed your free online IMUGA Traveller Declaration within 96 hours prior to arrival, and keep your passport and confirmed guesthouse reservation handy.",zh:"飞机降落维拉纳国际机场（MLE）后，跟随指示牌前往入境边检（Immigration）。请确保已在起飞前96小时内完成免费的 IMUGA 官方电子入境申报，并随身备好护照、往返机票行程单及已确认的民宿预订凭证。"},{en:"Once your 30-day tourist entry stamp is issued, collect your luggage from the carousel and pass through Customs X-ray screening into the public Arrivals Hall.",zh:"加盖30天免费旅游签证章后，前往转盘提取托运行李，并通过海关X光机检查步入到达迎宾大厅。"}]},{heading:{en:"2. Inside the Arrivals Forecourt: ATMs, SIM Cards & Meet-and-Greet",zh:"2. 到达大厅外廊：ATM取现、电话卡与接机汇合"},paragraphs:[{en:"Exiting the sliding glass doors of Customs places you in the covered Arrivals Forecourt. To your right are the official Dhiraagu and Ooredoo telecom kiosks for tourist SIM/eSIM packages, alongside Bank of Maldives (BML) ATMs and currency exchange counters.",zh:"走出海关玻璃门即进入有顶棚遮阳的到达外廊。右侧设有马尔代夫两大运营商 Dhiraagu 与 Ooredoo 的官方旅游电话卡柜台，以及马尔代夫银行（BML）ATM机与外币兑换处。"},{en:"Straight ahead (less than 60 metres from the exit) is the waterfront jetty promenade where island speedboats dock, and where airport representatives hold property name boards to escort you to your boat.",zh:"正前方不到60米处就是海滨快艇码头步道，前往各居民岛的定期快艇均停靠于此。民宿或快艇公司的机场代表会在此手举名牌迎接您并协助搬运行李登船。"}]}],officialReferenceUrl:"https://macl.aero",officialReferenceLabel:{en:"Maldives Airports Company Limited (MACL)",zh:"马尔代夫机场有限公司 (MACL) 官方网站"}},{id:"guide-speedboat-transfers",slug:"speedboat-transfers-in-the-maldives",category:"arrival-transfers",categoryLabel:{en:"Arrival & Transfers",zh:"抵达与交通接驳"},title:{en:"Scheduled Speedboat Transfers: Timings, Luggage & Booking",zh:"马尔代夫居民岛定期快艇接驳：班次、行李与预订须知"},summary:{en:"How scheduled inter-atoll speedboats operate from Velana Airport to Maafushi, Dhigurah, Fulidhoo, Thoddoo, and Ukulhas, and why flight arrival times matter.",zh:"了解从马累机场前往马富士、迪古拉、富力杜、托杜与乌库拉斯岛的定期快艇运作机制，以及如何根据国际航班时间衔接船班。"},heroImage:{url:"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Traveling_in_Maldives_-_Flickr_-_nattu.jpg/1920px-Traveling_in_Maldives_-_Flickr_-_nattu.jpg",alt:{en:"Boat cruising across brilliant turquoise lagoon waters toward a palm-dotted island in the Maldives",zh:"快艇穿越马尔代夫蔚蓝环礁水道前往居民岛"},credit:"Photo by Nattu Adnan / Wikimedia Commons (CC BY 2.0)"},lastReviewedDate:"2026-10-15",readingTimeMinutes:4,keyTakeaways:{en:["Scheduled speedboats are modern, covered twin- or triple-outboard vessels equipped with life jackets and cushioned seating.","Seats are always reserved in advance through your guesthouse so the boat manifest includes your flight number.","International flights landing before 15:00 local time connect easily with same-day afternoon speedboats to Ari and Vaavu Atolls; late-evening arrivals can still reach Maafushi or stay near the airport."],zh:["居民岛定期快艇均为配备全封闭遮阳顶棚、软垫座椅与救生衣的现代大马力双发或三发高速快艇。","快艇座位需统一通过所住民宿提前实名预订，以便船方登记您的国际航班号并在机场等候。","当地时间 15:00 前降落马累的国际航班通常可当天衔接前往南北阿里环礁与瓦武环礁的下午船班；晚间抵达航班仍可前往马富士岛或安排过渡住宿。"]},sections:[{heading:{en:"Typical Speedboat Durations from Velana Airport (MLE)",zh:"从维拉纳国际机场 (MLE) 出发的常规快艇航程"},paragraphs:[{en:"Journey times depend on the atoll distance and sea conditions across open channels (Kandu):",zh:"快艇航行时间取决于目标岛屿所在的环礁距离及当日海况："}],bulletPoints:{en:["Maafushi (Kaafu Atoll): 30–35 minutes (multiple departures morning through evening)","Fulidhoo (Vaavu Atoll): 70–85 minutes (typically morning and afternoon departures)","Thoddoo (Alif Alif Atoll): 75 minutes (daily afternoon and morning schedules)","Ukulhas (Alif Alif Atoll): 75–90 minutes (typically ~10:30 and ~16:00 departures)","Dhigurah (Alif Dhaal Atoll): 1 hour 45 minutes – 2 hours (typically ~11:00 and ~16:00 departures)"],zh:["马富士岛 Maafushi（卡夫环礁）：30–35 分钟（早中晚多班密集发船）","富力杜岛 Fulidhoo（瓦武环礁）：70–85 分钟（每日上下午固定班次）","托杜岛 Thoddoo（北阿里环礁）：约 75 分钟（每日固定班次）","乌库拉斯岛 Ukulhas（北阿里环礁）：75–90 分钟（通常约 10:30 与 16:00 发船）","迪古拉岛 Dhigurah（南阿里环礁）：1 小时 45 分钟 – 2 小时（通常约 11:00 与 16:00 发船）"]}},{heading:{en:"Friday Schedule Adjustments & Seasickness Tips",zh:"周五主麻日班次调整与防晕船贴士"},paragraphs:[{en:"On Fridays, mid-day boat departures pause between 11:30 and 13:30 for Jumu’ah prayers, shifting morning and afternoon departure times slightly. If you are prone to motion sickness, choose a seat toward the rear (stern) of the speedboat where wave motion is gentlest.",zh:"每周五（伊斯兰主麻日）中午 11:30 至 13:30 祈祷时段快艇暂停发船，当日班次时间会相应微调。若您容易晕船，登船后建议选择快艇后排靠走道座位，颠簸感最小。"}]}]},{id:"guide-domestic-flights",slug:"domestic-flights-in-the-maldives",category:"arrival-transfers",categoryLabel:{en:"Arrival & Transfers",zh:"抵达与交通接驳"},title:{en:"Domestic Flights in the Maldives: Reaching Southern & Outer Atolls",zh:"马尔代夫内陆航班指南：轻松飞往拉姆环礁与南阿里环礁"},summary:{en:"Flying from Velana Domestic Terminal to regional atoll airports such as Kadhdhoo (KDO) in Laamu Atoll and Maamigili (VAM) in South Ari Atoll.",zh:"详解从维拉纳机场国内航站楼搭乘马尔代夫内陆飞机前往拉姆环礁（KDO）与南阿里环礁（VAM）的换乘流程与行李规定。"},heroImage:{url:"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/Aerial_shot_of_a_small_island_on_a_coral_reef_in_the_Maldives.jpg/1920px-Aerial_shot_of_a_small_island_on_a_coral_reef_in_the_Maldives.jpg",alt:{en:"Aerial view of a small island perched on a coral reef ring in the Maldives",zh:"从内陆航班俯瞰马尔代夫珊瑚礁环抱的海岛与泻湖"},credit:"Photo by Dr. Ondřej Havelka / Wikimedia Commons (CC BY-SA 4.0)"},lastReviewedDate:"2026-10-15",readingTimeMinutes:4,keyTakeaways:{en:["The Domestic Terminal at Velana Airport (MLE) is a 3-minute covered walk north of International Arrivals.","Domestic flights operate day and night on scheduled Dash-8 / ATR turboprop aircraft with air-conditioned cabins and panoramic window views of the atolls.","For Reveries Diving Village on Laamu Gan, a 40-minute flight to Kadhdhoo (KDO) connects directly to a 15-minute road transfer across the bridge causeway."],zh:["维拉纳机场国内航站楼（Domestic Terminal）位于国际到达出口北侧，沿有顶棚连廊步行仅需3分钟。","内陆航班采用全空调客舱的涡桨客机，白昼与夜间均可起降，飞行途中可从舷窗俯瞰绝美的环礁珍珠链。","前往拉姆甘岛 Reveries Diving Village 只需搭乘40分钟内陆航班至 Kadhdhoo 机场（KDO），随后乘专车经跨海大桥15分钟直达酒店。"]},sections:[{heading:{en:"How Domestic Flight Bookings Work",zh:"内陆机票如何预订与衔接"},paragraphs:[{en:"Domestic tickets for visitors staying at island properties are typically booked directly through the guesthouse or travel agency under contracted tourist fares, ensuring automatic re-accommodation if your international flight is delayed.",zh:"前往海岛民宿的内陆机票通常由民宿或旅行平台按旅游协议价为您统一代订，这样若遇国际航班延误，地勤人员可自动为您免费改签下一班内陆飞机。"},{en:"Standard baggage allowance is 20 kg checked luggage plus 5 kg cabin baggage per passenger.",zh:"常规免费行李额为每位乘客 20 公斤托运行李 + 5 公斤手提行李。"}]}]},{id:"guide-local-transport-ferries",slug:"local-island-transportation-and-mtcc-ferries",category:"arrival-transfers",categoryLabel:{en:"Arrival & Transfers",zh:"抵达与交通接驳"},title:{en:"Local Island Transportation & MTCC Public Ferries",zh:"居民岛岛内交通与 MTCC 公共渡轮指南"},summary:{en:"Getting around car-free coral islands on foot or by bicycle, plus how the MTCC public dhoni ferry network operates across the central atolls.",zh:"在无车珊瑚岛上步行、骑行与乘坐电动接驳车的体验，以及马尔代夫交通签约公司（MTCC）公共渡轮的运行规则。"},heroImage:{url:"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/10/Buiobuione-Maldive-Maafushi-Town-hammock.jpg/1920px-Buiobuione-Maldive-Maafushi-Town-hammock.jpg",alt:{en:"Beach hammock strung between palm trees overlooking the turquoise Indian Ocean on Maafushi Island, Maldives",zh:"马尔代夫居民岛海滨椰树间面向碧蓝印度洋的吊床"},credit:"Photo by Buiobuione / Wikimedia Commons (CC BY-SA 4.0)"},lastReviewedDate:"2026-10-15",readingTimeMinutes:4,keyTakeaways:{en:["Most Maldivian inhabited islands (Fulidhoo, Ukulhas, Maafushi, Thoddoo, Dhigurah) have compacted coral-sand streets and are explored on foot or by bicycle.","Guesthouses provide complimentary luggage pickup at the island jetty upon arrival and departure.","MTCC Public Ferries are slow, economical wooden ferries primarily serving local residents; they never operate on Fridays."],zh:["绝大多数马尔代夫居民岛（如富力杜、乌库拉斯、马富士、托杜与迪古拉）均为天然珊瑚白沙街道，全岛步行或骑自行车即可轻松探索。","所有认证民宿均提供上下岛时的码头免费行李接送服务。","MTCC 公共渡轮为服务当地居民的经济型慢船，票价低廉但耗时较长，且每周五全天停航。"]},sections:[{heading:{en:"Walking, Cycling & Harbour Buggies",zh:"步行、自行车与码头行李车"},paragraphs:[{en:"On compact islands like Fulidhoo (670 m long) and Ukulhas (1 km long), every beach, caf\xe9, and jetty is within a 3-to-8-minute walk. On broader Thoddoo Island, bicycles are the primary mode of transport through the fruit plantations. On Laamu Gan, an 18-kilometre paved road connects four islands across bridge causeways.",zh:"在富力杜（全长仅670米）与乌库拉斯（长1公里）等紧凑型海岛上，任何海滩、餐厅与码头都在3至8分钟步程之内。在宽阔的托杜岛，自行车是穿行果园的最佳交通工具；而在拉姆甘岛，18公里跨海柏油公路支持汽车与单车跨岛通行。"}]}],officialReferenceUrl:"https://mtcc.mv",officialReferenceLabel:{en:"MTCC Public Transport Schedules",zh:"MTCC 马尔代夫公共渡轮官方网站"}},{id:"guide-currency-payments",slug:"currency-payments-atms-and-taxes-in-maldives",category:"practical-info",categoryLabel:{en:"Practical Information",zh:"实用出行信息"},title:{en:"Currency, USD Acceptance, ATMs & Maldivian Tourism Taxes",zh:"货币支付、美元现金要求、ATM分布与马尔代夫旅游税费详解"},summary:{en:"Understanding Maldivian Rufiyaa (MVR), why US Dollars must be crisp post-2013 notes, where Bank of Maldives ATMs are located, and how TGST and Green Tax work.",zh:"全面了解马尔代夫拉菲亚（MVR）汇率、为什么美元现金必须是2013版后无折损新钞、各岛ATM分布及绿色税（Green Tax）标准。"},heroImage:{url:"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/Male-total.jpg/1920px-Male-total.jpg",alt:{en:"Aerial view of Mal\xe9, the island capital of the Maldives surrounded by deep blue ocean",zh:"马尔代夫首都马累岛全景航拍"},credit:"Photo by Shahee Ilyas / Wikimedia Commons (CC BY-SA 3.0)"},lastReviewedDate:"2026-10-15",readingTimeMinutes:5,keyTakeaways:{en:["Official Currency: Maldivian Rufiyaa (MVR), pegged at approximately 15.42 MVR = 1 USD.","US Dollars (USD) are universally accepted at guesthouses, dive centres, and speedboat operators, provided notes are crisp, clean, post-2013 series without tears or ink stamps.","Tourism Taxes: 17% TGST, 10% Service Charge, and statutory Green Tax (USD 6 per person/night at guesthouses with ≤50 rooms; USD 12 at larger properties)."],zh:["法定货币：马尔代夫拉菲亚（MVR），官方固定汇率约为 1 美元 = 15.42 拉菲亚。","美元（USD）在所有民宿、潜店与快艇公司普遍通用，但请注意：当地银行仅接收 2013 年及以后版别、无破损、无折痕、无印章涂鸦的崭新美元纸币。","法定税费：房价与活动适用 17% 旅游商品服务税（TGST）、10% 服务费及政府绿色税（50间房及以下民宿为每人每晚 6 美元；50间房以上酒店为每人每晚 12 美元）。"]},sections:[{heading:{en:"ATMs & Card Payments on Featured Islands",zh:"六大精选居民岛 ATM 机分布与刷卡提示"},paragraphs:[{en:"Visa and Mastercard credit/debit cards are accepted at all six featured guesthouses. Bank of Maldives (BML) ATMs dispensing local Rufiyaa (MVR) are present at Velana Airport (MLE) and on Maafushi, Dhigurah, Thoddoo, Ukulhas, and Laamu Gan.",zh:"本平台精选的六家民宿均支持 Visa 和 Mastercard 信用卡结算。维拉纳国际机场（MLE）以及马富士岛、迪古拉岛、托杜岛、乌库拉斯岛和拉姆甘岛均设有马尔代夫银行（BML）ATM取款机（吐出当地货币拉菲亚 MVR）。"},{en:"Important exception: Fulidhoo Island in Vaavu Atoll does not currently have an ATM on the island, so visitors heading to Fulidhoo should carry sufficient USD or MVR cash from the airport alongside their bank card.",zh:"特别提示：瓦武环礁的富力杜岛（Fulidhoo）目前岛上未设ATM机，前往富力杜岛的旅客请提前在机场备好适量美元或拉菲亚现金。"}]}]},{id:"guide-island-customs",slug:"local-island-customs-and-cultural-etiquette",category:"culture-etiquette",categoryLabel:{en:"Culture & Etiquette",zh:"海岛文化与礼仪"},title:{en:"Local Island Customs: Experiencing Maldivian Community Life Respectfully",zh:"马尔代夫居民岛风俗礼仪：尊重与融入当地海岛生活"},summary:{en:"Key cultural practices on inhabited Maldivian islands, including the alcohol prohibition, Friday prayer hours, Ramadan observance, and community hospitality.",zh:"了解马尔代夫居民岛的核心宗教与文化习俗，包括禁酒规定、周五主麻日祈祷时段及社区交往礼仪。"},heroImage:{url:"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c1/Rasdhoo_street_-_panoramio.jpg/1920px-Rasdhoo_street_-_panoramio.jpg",alt:{en:"Quiet sandy village street lined with pastel local homes and palm trees on a Maldivian island",zh:"马尔代夫居民岛宁静的白沙街巷与当地民居"},credit:"Photo by georama / Wikimedia Commons (CC BY 3.0)"},lastReviewedDate:"2026-10-15",readingTimeMinutes:4,keyTakeaways:{en:["The Republic of Maldives is a 100% Sunni Muslim country with warm, welcoming island communities.","Alcohol is strictly prohibited from being brought into the country through customs and is not sold on inhabited islands.","Friday (particularly 11:30–13:30) is the weekly congregational prayer time when local shops pause operations."],zh:["马尔代夫共和国是100%信仰逊尼派伊斯兰教的国家，岛民社区民风淳朴、友善好客。","法律严禁旅客携带任何酒类入境（海关将予暂扣代管），且所有有人居住的居民岛上均不售卖含酒精饮品。","每周五是当地的休息与礼拜日，中午 11:30 至 13:30 主麻日聚礼期间，街区小店与轮渡会暂停营业。"]},sections:[{heading:{en:"Alcohol & Pork Regulations",zh:"关于酒类与清真饮食的法律规定"},paragraphs:[{en:"Do not purchase duty-free alcohol en route to Velana Airport; customs scanners screen 100% of arriving bags and hold any alcoholic bottles in airport bond until your departure flight. On islands like Maafushi, licensed safari boats anchored offshore in the lagoon operate floating bars, while guesthouse restaurants serve fresh tropical juices, mocktails, and espresso.",zh:"切勿在出发机场免税店购买酒水带入马尔代夫；马累海关会对100%入境行李进行X光检查，任何酒类都会被暂扣于机场保管处直至您离境时发还。在马富士岛等海域，泻湖外锚泊的持牌游艇（Floating Bar）可合法供应酒水；而岛上餐厅则提供丰富的新鲜热带鲜榨果汁、无酒精特调莫吉托与现磨咖啡。"}]}]},{id:"guide-dress-code-bikini-beaches",slug:"appropriate-dress-on-inhabited-islands-and-bikini-beaches",category:"culture-etiquette",categoryLabel:{en:"Culture & Etiquette",zh:"海岛文化与礼仪"},title:{en:"Dress Code on Inhabited Islands & How Bikini Beaches Work",zh:"居民岛着装指南与“比基尼海滩 (Bikini Beach)”详解"},summary:{en:"Where to wear swimwear freely and what to wear when strolling through island villages, harbours, and caf\xe9s.",zh:"清晰解答在居民岛哪些区域可以自由穿比基尼拍照游泳，以及进入村落街道时的得体着装建议。"},heroImage:{url:"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Maafushi-Beach-Maldives.jpg/1920px-Maafushi-Beach-Maldives.jpg",alt:{en:"Coconut palms leaning over white coral sand on Maafushi Bikini Beach, Maldives",zh:"马尔代夫马富士比基尼海滩上的椰树与细白珊瑚沙"},credit:"Photo by Nicolai Edgar Andersen / Wikimedia Commons (CC BY-SA 3.0)"},lastReviewedDate:"2026-10-15",readingTimeMinutes:3,keyTakeaways:{en:["Every island we feature has a dedicated, signposted Bikini Beach (and excursion sandbanks/boats) where standard bikinis and swim trunks are 100% welcome.","When walking through village streets, jetties, ferries, and local shops, cover shoulders and knees (a breathable cotton t-shirt and shorts, skirt, or sarong)."],zh:["本平台精选的每一座海岛均设有风光绝佳的指定比基尼海滩（Bikini Beach），在该海滩、出海游船及无人沙洲上可100%自由穿着比基尼与泳裤。","当离开比基尼海滩进入村落街道、码头、渡轮或当地商店时，请穿好遮盖肩膀与膝盖的轻便外搭（如透气T恤配短裤、长裙或沙龙巾）。"]},sections:[{heading:{en:"Simple, Effortless Island Wardrobe",zh:"简单实用的海岛穿搭法则"},paragraphs:[{en:"You do not need heavy or restrictive clothing—lightweight linen or cotton shirts, knee-length shorts, sundresses with covered shoulders, or a beach sarong slipped over your swimwear when walking back from the Bikini Beach to your guesthouse is completely comfortable and appreciated by local residents.",zh:"您完全无需准备厚重拘束的衣物——只需随身备一件轻薄透气的棉麻衬衫、T恤、及膝短裤或长裙，在从比基尼海滩走回民宿途经村落小巷时套在泳衣外即可，既防晒又赢得当地居民的由衷尊重。"}]}]},{id:"guide-weather-seasons",slug:"maldives-weather-monsoons-and-marine-seasons",category:"weather-safety",categoryLabel:{en:"Weather & Safety",zh:"气候与安全须知"},title:{en:"Maldives Weather, Monsoons & Marine Life Seasons",zh:"马尔代夫气候季节、旱雨季特征与海洋生物最佳观测期"},summary:{en:"Comparing the dry Northeast Monsoon (Iruvai: December–April) and the marine-rich Southwest Season (Hulhangu: May–November).",zh:"对比12月至次年4月的东北季风旱季（Iruvai）与5月至11月浮游生物丰富、蝠鲼活跃的西南季风季（Hulhangu）。"},heroImage:{url:"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Maldives_tropical_island_%28Unsplash%29.jpg/1920px-Maldives_tropical_island_%28Unsplash%29.jpg",alt:{en:"Aerial view of a lush coral island ringed by white sand and a turquoise lagoon in the Maldives",zh:"马尔代夫被白沙滩与碧绿泻湖环绕的热带珊瑚岛航拍全景"},credit:"Photo by Ishan (@seefromthesky) / Wikimedia Commons (CC0)"},lastReviewedDate:"2026-10-15",readingTimeMinutes:4,keyTakeaways:{en:["Air temperatures remain warm year-round between 28\xb0C and 31\xb0C, with sea temperatures consistently around 28\xb0C–29\xb0C.","December to April (Iruvai Season) brings the calmest seas, lowest humidity, and highest underwater visibility.","May to November (Hulhangu Season) offers quieter beaches, passing tropical showers, and peak plankton blooms that draw large numbers of manta rays."],zh:["马尔代夫全年气温恒定在 28\xb0C 至 31\xb0C 之间，海水温度常年保持在舒适的 28\xb0C–29\xb0C，四季皆宜下水。","12月至次年4月（Iruvai 东北季风旱季）：风平浪静、阳光最充足、水下能见度极高。","5月至11月（Hulhangu 西南季风季）：性价比极高，虽偶有短暂热带阵雨，但丰富的浮游生物吸引了大量礁蝠鲼聚集，且南阿里环礁全年均可观测野生鲸鲨。"]},sections:[{heading:{en:"Year-Round Whale Sharks & Sea Turtles",zh:"全年皆可邂逅的野生鲸鲨与海龟"},paragraphs:[{en:"Unlike seasonal migration sites elsewhere, South Ari Atoll (Dhigurah) hosts resident juvenile whale sharks 365 days a year, and the sea turtles of Thoddoo and Ukulhas remain on their home reefs throughout every month.",zh:"与其他国家的季节性迁徙不同，南阿里环礁（迪古拉岛）的野生鲸鲨以及托杜岛、乌库拉斯岛房礁上的绿海龟与玳瑁均为常年栖息种群，一年365天均可安排出海与岸潜观赏。"}]}]},{id:"guide-mobile-connectivity",slug:"mobile-connectivity-sim-cards-and-wifi",category:"practical-info",categoryLabel:{en:"Practical Information",zh:"实用出行信息"},title:{en:"Mobile Connectivity, Tourist eSIMs & Island Wi-Fi",zh:"马尔代夫网络通讯、机场旅游电话卡/eSIM 与岛上 Wi-Fi 指南"},summary:{en:"4G/5G coverage across inhabited islands via Dhiraagu and Ooredoo Maldives, airport tourist SIM pickup, and WeChat / international app access.",zh:"详解马尔代夫两大运营商 Dhiraagu 与 Ooredoo 在各居民岛的 4G/5G 信号覆盖、机场电话卡办理及微信/海外应用流畅使用说明。"},heroImage:{url:"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/Floating_in_Maldives._%28Unsplash%29.jpg/1920px-Floating_in_Maldives._%28Unsplash%29.jpg",alt:{en:"Overhead view of crystal-clear shallow lagoon waters and boats in the Maldives",zh:"马尔代夫清澈见底的浅海泻湖与船只俯瞰图"},credit:"Photo by Ishan (@seefromthesky) / Wikimedia Commons (CC0)"},lastReviewedDate:"2026-10-15",readingTimeMinutes:3,keyTakeaways:{en:["Inhabited islands have dedicated telecom towers providing reliable 4G/5G mobile data across the island and nearby lagoons.","Official Dhiraagu and Ooredoo tourist SIM/eSIM counters are located immediately outside Customs at Velana Airport (MLE).","WeChat, WhatsApp, Alipay messaging, Google Maps, and international websites work without restriction in the Maldives."],zh:["有人居住的马尔代夫居民岛均建有独立通讯基站，全岛及周边泻湖 4G/5G 移动网络覆盖稳定。","走出马累机场海关出口右侧即是 Dhiraagu 与 Ooredoo 官方柜台，凭护照3分钟即可激活旅游大流量实体卡或 eSIM。","在马尔代夫境内，微信（WeChat）、WhatsApp、小红书、抖音及各类国际地图与网站均可直接无障碍流畅访问。"]},sections:[{heading:{en:"Guesthouse Wi-Fi vs. Tourist Data SIM",zh:"民宿免费 Wi-Fi 与旅游流量卡建议"},paragraphs:[{en:"All six verified guesthouses provide complimentary Wi-Fi in rooms and dining areas. However, purchasing a tourist data SIM or eSIM at Velana Airport is highly recommended so you remain connected during speedboat transfers and boat excursions.",zh:"全部六家认证民宿均提供免费 Wi-Fi。但我们依然强烈建议您在马累机场办理一张当地旅游流量卡或开通国际漫游数据包，以便在快艇航行、无人沙洲打卡及海豚巡航途中随时保持在线与分享美景。"}]}]},{id:"guide-visa-imuga-entry",slug:"maldives-visa-and-imuga-entry-requirements",category:"arrival-transfers",categoryLabel:{en:"Arrival & Transfers",zh:"抵达与交通接驳"},title:{en:"Visa on Arrival (Free 30-Day Entry) & Official IMUGA Declaration",zh:"马尔代夫30天免费免签/落地签政策与 IMUGA 官方电子入境申报教程"},summary:{en:"Official entry rules for international and Chinese travellers, passport validity requirements, and how to submit the mandatory free IMUGA form.",zh:"面向全球及中国公民的30天免签入境政策、护照有效期规定，以及入境前96小时内免费填写官方 IMUGA 电子申报表的完整说明。"},heroImage:{url:"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c9/Atoll._%28Unsplash%29.jpg/1920px-Atoll._%28Unsplash%29.jpg",alt:{en:"Aerial photograph of natural ring-shaped coral reefs and turquoise lagoons in a Maldivian atoll",zh:"马尔代夫天然环状珊瑚礁与翡翠色泻湖的高空航拍"},credit:"Photo by Syd Sujuaan / Wikimedia Commons (CC0)"},lastReviewedDate:"2026-10-15",readingTimeMinutes:4,keyTakeaways:{en:["A 30-day Tourist Visa is granted free of charge on arrival to all nationalities worldwide; Chinese citizens enjoy mutual 30-day visa-free entry.","All travellers must submit the free online IMUGA Traveller Declaration at imuga.immigration.gov.mv within 96 hours before arrival.","Never pay third-party websites for the IMUGA declaration—the official Maldives Immigration portal is 100% free."],zh:["马尔代夫对全球所有国籍旅客免费发放30天落地旅游签证；根据《中马互免签证协定》，持有效中国护照的公民可免签入境停留不超过30天。","所有入境旅客必须在航班抵达前 96 小时内，登录马尔代夫移民局官网（imuga.immigration.gov.mv）完成电子入境申报（生成二维码截屏保存）。","重要防骗提醒：官方 IMUGA 申报 100% 免费，请认准 .gov.mv 官方域名，切勿在任何第三方代填收费网站支付费用。"]},sections:[{heading:{en:"Documents Required at Maldives Immigration",zh:"入境边检需备齐的四项材料"},paragraphs:[{en:"To clear immigration smoothly at Velana International Airport (MLE), ensure each traveller has:",zh:"为确保在马累机场快速丝滑通关，请每位旅客随身备齐："}],bulletPoints:{en:["Machine-Readable Passport with at least 1 month validity (6 months validity strongly recommended by airlines for international boarding).","Completed IMUGA Traveller Declaration QR code (submitted within 96 hours prior to arrival).","Confirmed return or onward flight ticket.","Confirmed accommodation voucher at a registered Maldivian guesthouse, hotel, or resort."],zh:["有效期完好的护照（马尔代夫移民局要求至少1个月以上有效期，但为确保国内值机出境顺畅，强烈建议护照有效期在6个月以上）。","已完成填报的 IMUGA 电子申报二维码截图（起飞前96小时内提交）。","已确认的往返机票行程单（英文版）。","已确认的马尔代夫合法注册民宿或酒店入住确认单（Booking Voucher）。"]}}],officialReferenceUrl:"https://imuga.immigration.gov.mv",officialReferenceLabel:{en:"Official Maldives Immigration IMUGA Portal",zh:"马尔代夫移民局 IMUGA 官方免费申报入口"}},{id:"guide-safety-emergency",slug:"safety-medical-facilities-and-emergency-contacts",category:"weather-safety",categoryLabel:{en:"Weather & Safety",zh:"气候与安全须知"},title:{en:"Ocean Safety, Island Health Centres & Verified Emergency Numbers",zh:"海洋活动安全、各岛医疗中心与马尔代夫官方紧急求助电话"},summary:{en:"Essential reef and current awareness, island medical clinics, and official Maldives emergency hotlines (Police 119, Ambulance 102, Coast Guard 191, Tourist Police 1478).",zh:"浮潜洋流安全须知、居民岛24小时医疗中心分布，以及经核实的马尔代夫报警（119）、医疗急救（102）、海岸警卫队（191）与旅游警察热线。"},heroImage:{url:"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/Snorkeling_in_the_Indian_Ocean_in_the_Maldives..JPG/1920px-Snorkeling_in_the_Indian_Ocean_in_the_Maldives..JPG",alt:{en:"Snorkeller gliding over a shallow turquoise coral reef in the Maldives",zh:"在马尔代夫浅海珊瑚礁海域安全浮潜"},credit:"Photo by Rudolph A. Furtado / Wikimedia Commons (CC BY-SA 3.0)"},lastReviewedDate:"2026-10-15",readingTimeMinutes:4,keyTakeaways:{en:["Every inhabited island featured on our platform has a 24-hour Island Health Centre or Regional Hospital.","Always swim and snorkel with a buddy, wear fins when snorkelling near reef drop-offs, and ask your guesthouse host about daily tidal currents.","Verified Emergency Numbers: Police 119 \xb7 Ambulance 102 \xb7 MNDF Coast Guard 191 \xb7 Tourist Police 1478."],zh:["本平台精选的每一座居民岛均设有 24 小时社区医疗中心（Health Centre）或区域医院。","下水浮潜请务必结伴同行，在珊瑚礁断层边缘请穿戴脚蹼（或救生衣），并提前向民宿管家了解当日潮汐与洋流方向。","马尔代夫官方紧急电话：警察 119 \xb7 医疗急救 102 \xb7 海岸警卫队海上救援 191 \xb7 旅游警察热线 1478。"]},sections:[{heading:{en:"Verified Maldives Emergency & Medical Contacts",zh:"经核实的马尔代夫官方紧急电话名录"},paragraphs:[{en:"Keep these official numbers saved in your phone while travelling across the Maldivian atolls:",zh:"建议在出发前将以下马尔代夫官方应急号码保存在手机中："}],bulletPoints:{en:["Maldives Police Service Emergency: 119","Ambulance / Medical Emergency: 102","MNDF Coast Guard (Maritime Search & Rescue): 191","Fire & Rescue Service: 118","Maldives Tourist Police Hotline: 1478 (or +960 979-0070)","Indira Gandhi Memorial Hospital (IGMH, Mal\xe9): +960 333-5335","ADK Hospital (Mal\xe9): +960 331-3553"],zh:["马尔代夫报警电话（Police Emergency）：119","医疗急救电话（Ambulance）：102","国家国防军海岸警卫队海上搜救（Coast Guard）：191","消防救援（Fire & Rescue）：118","马尔代夫旅游警察专线（Tourist Police）：1478 或 +960 979-0070","马累 IGMH 公立综合医院：+960 333-5335","马累 ADK 私立综合医院：+960 331-3553"]}}]}]}}]);